package net.zartra.gui;
import java.io.File;import java.util.logging.Logger;import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import org.junit.Test;import static org.junit.Assert.*;
public class Goal2ActionChainStorageTest {@Test public void menuAndConditionalActionChainsRoundTrip()throws Exception{File dir=new File(System.getProperty("java.io.tmpdir"),"zgui-chain-"+System.nanoTime());MenuStorage s=new MenuStorage(dir,Logger.getLogger("test"));MenuDefinition m=new MenuDefinition("chain","Chain",3);ActionEntry open=new ActionEntry();open.type="MESSAGE";open.value="open";m.openActions.add(open);ActionEntry close=new ActionEntry();close.type="MESSAGE";m.closeActions.add(close);MenuItem i=new MenuItem(new ItemStack(Material.STONE),null);ActionEntry a=new ActionEntry();a.type="MESSAGE";ActionEntry success=new ActionEntry();success.type="MESSAGE";success.value="yes";a.successActions.add(success);ActionEntry failure=new ActionEntry();failure.type="MESSAGE";failure.value="no";a.failureActions.add(failure);i.actions(MenuClickType.LEFT).add(a);m.items.put(0,i);s.save(m);MenuDefinition r=s.load().get("chain");assertEquals("open",r.openActions.get(0).value);assertEquals(1,r.closeActions.size());ActionEntry ra=r.items.get(0).actions(MenuClickType.LEFT).get(0);assertEquals("yes",ra.successActions.get(0).value);assertEquals("no",ra.failureActions.get(0).value);}}